/// Parse TOML text into a JSON value.
/// Raises a `ParseError` for invalid input.
pub fn parse_toml(text : String) -> Json raise ParseError {
  let lines = text.split("\n").to_array()
  let mut result : Map[String, Json] = Map::new()
  let mut current_table : Array[String] = []
  let mut line_num = 0

  while line_num < lines.length() {
    let raw = lines[line_num]
    line_num = line_num + 1

    // Strip comments
    let line = strip_comment(raw)

    // Skip blank lines
    if line.trim().is_empty() {
      continue
    }

    // Table header
    if line[0] == '[' as Int {
      let rest = line.sub(start=1, end=line.length()).to_owned().trim()
      if rest[rest.length() - 1] == ']' as Int {
        let table_path_str = rest.sub(start=0, end=rest.length() - 1).to_owned().trim()
        let keys = parse_dotted_key(table_path_str)
        current_table = keys
      } else {
        raise ParseError::InvalidSyntax("invalid table header at line \(line_num)")
      }
      continue
    }

    // Key = value pair
    let eq_pos = line.find("=")
    if eq_pos == -1 {
      raise ParseError::InvalidSyntax("invalid syntax at line \(line_num)")
    }
    let key_str = line.sub(start=0, end=eq_pos).to_owned().trim()
    let val_str = line.sub(start=eq_pos + 1, end=line.length()).to_owned().trim()
    let keys = parse_dotted_key(key_str)
    let value = parse_value(val_str, line_num)

    // Insert value at full path (current_table + keys)
    let full_path = Array::new()
    for i = 0; i < current_table.length(); i = i + 1 {
      full_path.push(current_table[i])
    }
    for i = 0; i < keys.length(); i = i + 1 {
      full_path.push(keys[i])
    }

    set_at_path(result, full_path, value, line_num)
  }

  Json::object(result)
}

///|
suberror ParseError {
  DuplicateKey(String, String)
  InvalidSyntax(String)
} derive(Debug)

///|
fn strip_comment(line : String) -> String {
  let mut in_str = false
  let mut str_char = '"'
  let mut i = 0
  while i < line.length() {
    let c = line[i]
    if in_str {
      if c == '\\' as Int {
        i = i + 2
        continue
      }
      if c == str_char {
        in_str = false
      }
      i = i + 1
      continue
    }
    if c == '#' as Int {
      return line.sub(start=0, end=i).to_owned()
    }
    if c == '"' as Int {
      in_str = true
      str_char = '"'
    }
    i = i + 1
  }
  line
}

///|
fn parse_dotted_key(s : String) -> Array[String] {
  s.split(".").map(fn(x) { x.trim() }).filter(fn(x) { not x.is_empty() })
}

///|
fn parse_value(s : String, line_num : Int) -> Json raise ParseError {
  if s.is_empty() {
    raise ParseError::InvalidSyntax("empty value at line \(line_num)")
  }

  // String literal
  if s[0] == '"' as Int {
    return parse_string(s, line_num)
  }

  // Boolean
  if s == "true" {
    return Json::True
  }
  if s == "false" {
    return Json::False
  }

  // Array
  if s[0] == '[' as Int {
    return parse_array(s, line_num)
  }

  // Integer
  parse_int(s, line_num)
}

///|
fn parse_string(s : String, line_num : Int) -> Json raise ParseError {
  if s.length() < 2 || s[0] != '"' as Int {
    raise ParseError::InvalidSyntax("invalid string at line \(line_num)")
  }
  let mut i = 1
  let mut buf = StringBuilder::new()
  while i < s.length() && s[i] != '"' as Int {
    if s[i] == '\\' as Int {
      i = i + 1
      if i >= s.length() {
        raise ParseError::InvalidSyntax("incomplete escape at line \(line_num)")
      }
      match s[i] {
        '"' as Int => buf.write_char('"')
        '\\' as Int => buf.write_char('\\')
        'n' as Int => buf.write_char('\n')
        't' as Int => buf.write_char('\t')
        _ => raise ParseError::InvalidSyntax("invalid escape \\\(Char::from_int(s[i])) at line \(line_num)")
      }
    } else {
      buf.write_char(Char::from_int(s[i]))
    }
    i = i + 1
  }
  if i >= s.length() {
    raise ParseError::InvalidSyntax("unterminated string at line \(line_num)")
  }
  Json::string(buf.to_string())
}

///|
fn parse_int(s : String, line_num : Int) -> Json raise ParseError {
  // Handle optional sign
  let mut text = s
  let is_neg = if text.length() > 0 && text[0] == '-' as Int {
    text = text.sub(start=1, end=text.length()).to_owned()
    true
  } else if text.length() > 0 && text[0] == '+' as Int {
    text = text.sub(start=1, end=text.length()).to_owned()
    false
  } else {
    false
  }

  if text.is_empty() || text.split("").to_array().iter().any(fn(c) { c != "" && (c[0] < '0' as Int || c[0] > '9' as Int) }) {
    raise ParseError::InvalidSyntax("invalid integer at line \(line_num)")
  }

  let n : Int = @string.from_str(s) catch {
    _ => raise ParseError::InvalidSyntax("invalid integer at line \(line_num)")
  }
  Json::number(n.to_double(), repr=s)
}

///|
fn parse_array(s : String, line_num : Int) -> Json raise ParseError {
  // Simple array parser: [val1, val2, ...]
  let trimmed = s.trim()
  if trimmed.length() < 2 || trimmed[0] != '[' as Int {
    raise ParseError::InvalidSyntax("invalid array at line \(line_num)")
  }
  if trimmed[trimmed.length() - 1] != ']' as Int {
    raise ParseError::InvalidSyntax("unterminated array at line \(line_num)")
  }

  let inner = trimmed.sub(start=1, end=trimmed.length() - 1).to_owned().trim()
  if inner.is_empty() {
    return Json::Array([])
  }

  // Split by top-level commas (not inside quotes)
  let items = split_array_elements(inner, line_num)
  let json_items = items.map(fn(item) { parse_value(item.trim(), line_num) })
  Json::Array(json_items)
}

///|
fn split_array_elements(s : String, line_num : Int) -> Array[String] raise ParseError {
  let mut items : Array[String] = []
  let mut depth = 0
  let mut in_str = false
  let mut start = 0
  let mut i = 0
  while i < s.length() {
    let c = s[i]
    if in_str {
      if c == '\\' as Int {
        i = i + 2
        continue
      }
      if c == '"' as Int {
        in_str = false
      }
      i = i + 1
      continue
    }
    if c == '"' as Int {
      in_str = true
      i = i + 1
      continue
    }
    if c == '[' as Int {
      depth = depth + 1
    } else if c == ']' as Int {
      depth = depth - 1
    } else if c == ',' as Int && depth == 0 {
      items.push(s.sub(start=start, end=i).to_owned().trim())
      start = i + 1
    }
    i = i + 1
  }
  if start < s.length() {
    let last = s.sub(start=start, end=s.length()).to_owned().trim()
    if not last.is_empty() {
      items.push(last)
    }
  }
  items
}

///|
fn set_at_path(
  root : Map[String, Json],
  path : Array[String],
  value : Json,
  line_num : Int
) -> Unit raise ParseError {
  let mut current_map = root
  let mut i = 0
  while i < path.length() - 1 {
    let key = path[i]
    let child = current_map[key] or {
      let new_map = Map::new()
      current_map[key] = Json::object(new_map)
      new_map
    }
    match child {
      Json::Object(m) => current_map = m
      _ => raise ParseError::DuplicateKey(key, "path segment is not a table")
    }
    i = i + 1
  }

  let last_key = path[path.length() - 1]
  if current_map.contains(last_key) {
    raise ParseError::DuplicateKey(
      last_key,
      "duplicate key at line \(line_num)"
    )
  }
  current_map[last_key] = value
}
